function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}

const input = $json.body || $json;
const assetId = String(input.assetId || '').trim();
const reviewNotes = String(input.reviewNotes || 'Promoted via API').trim();
const baseUrl = String(input.baseUrl || 'http://192.168.0.194:9000').replace(/[/]$/, '');

if (!assetId) {
  throw new Error('Missing required field: assetId');
}

return [{
  json: {
    assetId,
    assetIdSql: sql(assetId),
    reviewNotes,
    reviewNotesSql: sql(reviewNotes),
    reviewNotesJsonSql: sql(JSON.stringify(reviewNotes)),
    baseUrl
  }
}];

const params = $('Normalize Promote Request').first().json;
const promoted = $input.first().json;

if (!promoted || !promoted.asset_id) {
  return [{
    json: {
      promoted: false,
      reason: 'Asset not found or promotion failed',
      assetId: params.assetId
    }
  }];
}

return [{
  json: {
    promoted: true,
    assetId: promoted.asset_id,
    avatar: promoted.avatar,
    scene: promoted.scene,
    assetType: promoted.asset_type,
    url: `${params.baseUrl}/${promoted.bucket}/${promoted.object_path}`,
    bucket: promoted.bucket,
    objectPath: promoted.object_path,
    mimeType: promoted.mime_type,
    status: promoted.status,
    sha256: promoted.sha256,
    canonicalGroup: promoted.canonical_group,
    reviewNotes: promoted.review_notes,
    createdAt: promoted.created_at
  }
}];
